mod solution;

fn main() {
    let cases = [
    (r#"[4,8,15,16,23,42]"#, r#"16"#),
    (r#"[1,2,3,4,5]"#, r#"3"#),
    (r#"
[1,2,3,4,5]
"#, r#"3"#),
    (r#"  
[4,8,15,16,23,42]
  "#, r#"16"#),
    ];
    for (case_index, (input, expected)) in cases.iter().enumerate() {
        if solution::solve(input) != *expected {
            eprintln!("PRIVATE CASE {} FAILED", case_index + 1);
            std::process::exit(1);
        }
    }
    println!("PASS slow-fast");
}
